-- Create "listings" table
CREATE TABLE "public"."listings" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "slug" text NOT NULL, "title" text NOT NULL, "description" text NOT NULL DEFAULT '', "listing_type" text NOT NULL, "property_type" text NOT NULL, "status" text NOT NULL DEFAULT 'draft', "price" bigint NOT NULL, "bedrooms" smallint NULL, "bathrooms" smallint NULL, "area" integer NULL, "city" text NOT NULL, "locality" text NOT NULL DEFAULT '', "address" text NOT NULL DEFAULT '', "featured" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "listings_slug_key" UNIQUE ("slug"), CONSTRAINT "listings_area_check" CHECK (area > 0), CONSTRAINT "listings_bathrooms_check" CHECK (bathrooms >= 0), CONSTRAINT "listings_bedrooms_check" CHECK (bedrooms >= 0), CONSTRAINT "listings_listing_type_check" CHECK (listing_type = ANY (ARRAY['sale'::text, 'rent'::text])), CONSTRAINT "listings_price_check" CHECK (price >= 0), CONSTRAINT "listings_property_type_check" CHECK (property_type = ANY (ARRAY['apartment'::text, 'house'::text, 'villa'::text, 'plot'::text, 'commercial'::text, 'other'::text])), CONSTRAINT "listings_status_check" CHECK (status = ANY (ARRAY['draft'::text, 'active'::text, 'sold'::text, 'rented'::text])));
-- Create index "listings_status_created_at_idx" to table: "listings"
CREATE INDEX "listings_status_created_at_idx" ON "public"."listings" ("status", "created_at" DESC);
-- Create "salesman_profile" table
CREATE TABLE "public"."salesman_profile" ("id" smallint NOT NULL DEFAULT 1, "name" text NOT NULL, "phone" text NOT NULL, "email" text NOT NULL DEFAULT '', "bio" text NOT NULL DEFAULT '', "photo_path" text NULL, "country_code" text NOT NULL DEFAULT 'IN', "currency" text NOT NULL DEFAULT 'INR', "area_unit" text NOT NULL DEFAULT 'sqft', "admin_password_hash" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "salesman_profile_area_unit_check" CHECK (area_unit = ANY (ARRAY['sqft'::text, 'sqm'::text])), CONSTRAINT "salesman_profile_id_check" CHECK (id = 1));
-- Create "listing_media" table
CREATE TABLE "public"."listing_media" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "listing_id" uuid NOT NULL, "path" text NOT NULL, "media_type" text NOT NULL DEFAULT 'image', "position" integer NOT NULL DEFAULT 0, "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "listing_media_listing_id_fkey" FOREIGN KEY ("listing_id") REFERENCES "public"."listings" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "listing_media_media_type_check" CHECK (media_type = ANY (ARRAY['image'::text, 'video'::text])));
-- Create index "listing_media_listing_id_position_idx" to table: "listing_media"
CREATE INDEX "listing_media_listing_id_position_idx" ON "public"."listing_media" ("listing_id", "position");
